WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, COUNT_IF(method = 'card') AS card_events, STDDEV_SAMP(amount) AS amount_stddev, COUNT_IF(method = 'bank_transfer') AS bank_transfer_events, DENSE_RANK() OVER (PARTITION BY CASE WHEN island_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT_IF(method = 'bank_transfer') DESC) AS bank_transfer_events_dense_rank FROM sessionized GROUP BY island_id_tier, week_start ORDER BY amount_stddev DESC;
